void floydWarshall_20(vector<vector<int>>& dist) { int n = dist.size(); for (int k = 0; k < n; ++k) for (int i = 0; i < n; ++i) for (int j = 0; j < n; ++j) dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]); }
int bfsReachableNodes_20(const vector<vector<int>>& adj, int s) { int V = adj.size(), count = 0; vector<bool> seen(V, false); queue<int> q; seen[s] = true; q.push(s); while (!q.empty()) { int u = q.front(); q.pop(); ++count; for (int nxt : adj[u]) if (!seen[nxt]) { seen[nxt] = true; q.push(nxt); } } return count; }
